Wire up the new service methods in the daemon.

**File: packages/daemon/src/local-client.ts**

```typescript
async getChildSessions(parentSessionId: string): Promise<Session[]> {
  return listChildSessions(parentSessionId);  // from db.ts
}

async stopWithChildren(sessionId: string): Promise<void> {
  // Recursive: stop children first, then parent
  const children = await this.getChildSessions(sessionId);
  for (const child of children) {
    if (!isTerminalStatus(child.status)) {
      await this.stopWithChildren(child.id);  // recursive
    }
  }
  await this.stop(sessionId);
}
```

